@pytest.mark.parametrize('case', ['operations', 'refund']) def test_end_to_end_real_planner_and_business_models(model, case, record_property): settings = Settings.from_env() if settings.mode != 'live': pytest.fail('End-to-end registry requires M4_MODE=live') registry = CapabilityRegistry() for agent in (SingleAgent(model, mode='live'), ReActAgent(model, mode='live', max_rounds=3), WeeklyReportAgent(model, mode='live'), create_agent(settings), PromotionAgent(), DataFusionModule(), RefundWorkflow()): registry.register(agent.manifest, agent) goals = { 'operations': ('融合2026年第41周订单、行为和营销数据，生成周报，再依据周报制定下周大促方案，预算10万元。', {'m6.data_fusion', 'm3.weekly_report', 'm5.promotion_plan'}), 'refund': ('查询订单2025101234，再按查询得到的订单金额申请整单退款，原因是买错了。', {'m2.order_tracking', 'm7.refund_approval'}), } goal, expected = goals[case] outcome = DynamicPlanner(registry, configured_model(), max_repairs=0).plan(goal) record_property('planning_result', outcome.model_dump_json()) assert outcome.plan is not None, outcome.model_dump_json() assert {step.capability_id for step in outcome.plan.steps} == expected assert len(outcome.plan.steps) == len(expected) report = Executor(registry).execute(outcome.plan) record_property('execution_report', report.model_dump_json()) assert report.status == ('completed' if case == 'operations' else 'waiting_approval'), report.model_dump_json() steps = {step.capability_id: step for step in report.steps.values()} if case == 'operations': assert steps['m3.weekly_report'].inputs['fused_data'] == steps['m6.data_fusion'].result.data['fused_data'] > assert steps['m5.promotion_plan'].inputs['budget_amount'] == 10000000 E assert 1000000 == 10000000
